terraform {
  backend "s3" {
    bucket       = "tf-state-proyecto"
    key          = "prod/terraform.tfstate"
    region       = "us-east-1"
    encrypt      = true
    use_lockfile = true
  }
}

terraform {
  backend "gcs" {
    bucket = "tf-state-proyecto"
    prefix = "prod"
  }
}

terraform {
  backend "azurerm" {
    resource_group_name  = "rg-tfstate"
    storage_account_name = "sttfstateproyecto"
    container_name       = "tfstate"
    key                  = "prod.terraform.tfstate"
    use_azuread_auth     = true
  }
}

